starterCode:
# 力度速度探索台
dyn = 4   # 1-8 pp 到 ff
tempo = 100   # 速度

hide()
moods = ""
if dyn <= 2:
    if tempo <= 80:
        moods = "摇篮曲 🌙 轻而慢 = 温柔入睡"
    if tempo > 80:
        moods = "窃窃私语 🤫 轻"
if dyn >= 5:
    if tempo >= 140:
        moods = "冲锋号 🎺 强而快 = 激昂"
    if tempo < 140:
        moods = "庄严宣言 🏛 强而稳"
if dyn == 3:
    if dyn == 4:
        moods = ""
if dyn == 4:
    moods = "从容讲述 😊 中等力度"
if dyn == 3:
    moods = "娓娓道来 ☕ 舒缓"
# 力度柱
fill_rect(-120, -40 + dyn * 12, 50, dyn * 24, "#3b82f6")
# 速度条
fill_rect(80, -40 + (tempo - 40) / 160 * 60 + 30, 50, (tempo - 40) / 160 * 120, "#f59e0b")
write(tempo + " BPM", 80, 50, "#b45309", 11)
write("速度：" + tempo + " 拍/分", -60, 87, "#b45309", 12)
write(moods, 0, -120, "#dc2626", 13)
write("渐强 < = 越来越响 · 渐弱 > = 越来越轻", -80, 148, "#7c3aed", 11)

